export function slugify(value) {
  throw new Error('not implemented');
}

import { slugify } from '../src/slug.js';
const cases = [['Hello World', 'hello-world'], ['  Trim  me  ', 'trim-me'], ['Crème Brûlée', 'creme-brulee'], ['a -- b', 'a-b'], ['', '']];
for (const [input, expected] of cases) {
  const actual = slugify(input);
  if (actual !== expected) {
    console.error(`slugify(${JSON.stringify(input)}) returned ${JSON.stringify(actual)}, expected ${JSON.stringify(expected)}`);
    process.exit(1);
  }
}

export function total(items) {
  return items.reduce((sum, item) => sum + item.price, 0);
}

import { total } from '../src/cart.js';
if (total([{ price: 1 }, { price: 2 }]) !== 3) {
  console.error('total of plain prices changed');
  process.exit(1);
}

